  'copre|Fante di Bastoni|capovolta': [
    'Questa tua faccenda pretende un bersaglio nuovo a ogni giro e non concede a niente un secondo giorno. L\'interesse non le manca: le manca che resti sullo stesso punto il tempo di scaldarlo.',
