  'copre|Regina di Bastoni|capovolta': [
    'Una corrente verso l\'esterno attraversa la tua domanda: lo sguardo corre a un altro fuoco per vedere quanto scalda, mentre il centro da cui partiva il calore resta senza nessuno che lo guardi.',
