  'copre|Tre di Denari|capovolta': [
    'Questa forza pretende dalla tua questione che ogni parte abbia un nome e una mano assegnata: non ammette compiti dati per sottinteso; dove il nome manca la pretesa cade su tutti e su nessuno.',
