  'copre|Sei di Denari|dritta': [
    'Una forza di circolazione lavora sulla tua domanda: fa passare di mano quello che c\'è, misura la parte di ciascuno con la bilancia alzata, poi rimette in giro quanto ha appena consegnato.',
