  'copre|Sette di Denari|dritta': [
    'Il valore nella tua domanda si conta sul tempo che una cosa ha già dentro, non su quello che mostra fuori: un frutto verde pesa quanto le settimane che lo compongono. La fretta non entra in questo prezzo.',
    'Suona bassa la nota su questa faccenda: è il registro di chi sta appoggiato alla zappa e guarda, senza parlare al posto delle piante. Il discorso dentro la tua domanda procede a frasi lunghe.',
