  'copre|Regina di Denari|capovolta': [
    'Suona su questa tua faccenda il registro di un elenco letto a mano a mano: la spesa, le scadenze, i bisogni di ciascuno. L\'elenco è ordinato e in una riga manca il destinatario, cioè chi lo scrive.',
