  'copre|Sette di Spade|dritta': [
    'Un\'astuzia silenziosa sta prelevando una parte della tua questione e lascia il resto dov\'è: lavora senza annunciarsi, cosicché il guadagno riguarda un pezzo scelto e non l\'insieme.',
