  ],
  'corona|La Giustizia|capovolta': [
    'Al suo pieno rendimento questa forza riporterebbe sotto il tuo nome l\'unica parte del conto che è davvero tua: non tutte le colpe del mondo, non il caso, soltanto la riga che ti appartiene per via diretta.',
    'Quello che questa forza, al suo meglio, salva nella tua questione è la possibilità di un pareggio: finché il conto resta attribuito al caso nessuno lo può leggere; riconosciuto, almeno torna sul tavolo come cifra.',
    'Il punto oltre il quale questa forza non sale, nella tua faccenda, è il nome esatto messo sopra una conseguenza: la riconduce a chi la produce e non la alleggerisce di un grammo.',
