  'corona|L\'Eremita|dritta': [
    'Fra come la tua questione sta adesso e quanto potrebbe chiarirsi resta aperto un margine: è lo spazio che un silenzio cercato sa riempire, un passo illuminato per volta.',
    'Il genere di bene al suo massimo qui è lucidità, non conforto: una comprensione guadagnata nel tuo raccoglimento, di quelle che nessuno può consegnarti da fuori.',
    'La lanterna di questa forza, al suo meglio, può mostrare alla tua questione un passo chiaro per volta; quello che non arriva a dare è la mappa intera in una sola occhiata.',
  ],
  'corona|L\'Eremita|capovolta': [
    'Al suo pieno rendimento questa forza darebbe alla tua questione la differenza vista con chiarezza fra un raccoglimento che insegna e un ritiro che tiene lontano, con la lanterna puntata anche sul rientro.',
    'Quello che questa forza al suo meglio lascia intero nella tua questione è il filo con gli altri: assottigliato dalla distanza, mai reciso, percorribile ancora nei due sensi.',
