  ],
  'corona|La Ruota della Fortuna|dritta': [
    'Al suo meglio questo girare lascia intero il fatto che niente nella tua questione sia fissato per sempre: quello che salva è la mobilità, cioè la possibilità che un assetto duro si sciolga da sé.',
    'Di che genere è il bene più alto qui: movimento e non comodità. Il massimo della tua domanda è una rotazione che rimette in gioco quello che pareva assegnato, mai una sistemazione migliore in cui fermarsi.',
    'Il tetto di questa forza è il cambiamento stesso: può rovesciare un assetto della tua questione e non può scegliere dove arrestarlo. L\'altezza qui è il moto, il suo limite è il non avere mano.',
  ],
  'corona|La Ruota della Fortuna|capovolta': [
    'Al suo pieno rendimento un giro che si ripete sa dare una cosa sola e la dà intera: la forma esatta del cerchio che la tua questione ripercorre, misurata sul punto da cui ogni volta riparte.',
    'Fra il punto dove la tua questione gira adesso e quanto varrebbe lo stesso moto con una presa sopra, la distanza ancora aperta misura quello che manca: un appiglio, non più spinta.',
    'Se nulla lo sprecasse, questo meccanismo scomposto mostrerebbe quale dei suoi denti salta: il tuo problema apparirebbe nella sua misura, un giro guasto in un punto preciso invece di una sorte contraria.',
  ],
  'corona|La Forza|dritta': [
    'Al suo meglio questa mitezza salva l\'istinto invece di spegnerlo: la belva che riguarda la tua questione resta viva, calda, intera, con una mano posata sul collo che non stringe mai.',
    'Di genere, il massimo qui è docilità e non vittoria: alla tua domanda spetta un ardore che obbedisce di buon grado; la differenza si sente tutta nella mano che lo tiene.',
    'Il punto oltre il quale questa dolcezza non sale è il consenso: alla tua questione può toccare un istinto che segue perché acconsente, non uno piegato con la stretta.',
  ],
  'corona|La Forza|capovolta': [
    'Il meglio che questa carta sa dare al rovescio è una mano che si apre: la durezza puntata contro la tua stessa tenuta può allentarsi; il governo torna dove la stretta lo perdeva.',
    'Lo spazio fra una presa serrata sul proprio ardore e un palmo aperto è tutto quello che questa carta può recuperare alla tua questione; la misura è in mitezza invece che in disciplina.',
