  'corona|L\'Appeso|dritta': [
    'Il massimo qui è fatto di una sola materia: lo sguardo girato sottosopra, che della tua questione mostra la faccia tenuta nascosta finché la guardavi dall\'angolo comodo.',
    'Questa immobilità, al suo meglio, dà alla tua domanda una comprensione che l\'agitazione non produce; non arriva a dare la mossa successiva, perché capire da rovescio è un mestiere a sé.',
    'Tenuta a pieno, questa pausa salva intatta la cosa che la fretta consuma per prima: il tempo in cui una comprensione matura da sé, senza che tu la tiri per le foglie.',
  ],
  'corona|L\'Appeso|capovolta': [
    'Il bene che questa forza dà alla tua questione è di specie amara: chiarezza sul conto invece di conforto. Il tetto qui è vedere che quella rinuncia non nutre nessuno, nemmeno chi la fa.',
    'Più su di questo non sale: l\'altezza in gioco è il riconoscimento esatto di un\'attesa che ha smesso di insegnare qualcosa alla tua questione.',
    'Al rendimento pieno questa sospensione vuota dà un conto onesto: quanto ti costa restare fermo, a fronte di quanto di quel costo arriva davvero a qualcuno.',
