  'corona|La Morte|dritta': [
    'Il massimo in gioco per la tua questione è fatto di due cose soltanto: un taglio netto dove il tempo di una forma è esaurito e uno spazio che resta vuoto e pulito dietro quel taglio.',
    'Al suo meglio questa forza libera il posto nel tuo caso e non lo arreda: arriva a chiudere senza residui quello che è esaurito, mentre quello che nasce dopo non è materia sua.',
    'Quello che resta intero, quando questa forza dà tutto, è ciò che nella tua domanda era vivo davvero: il taglio prende soltanto ciò che non ha più tempo.',
