  'corona|La Morte|capovolta': [
    'Il genere di bene che questa forza porta al massimo è lucidità e non sollievo: la tua presa si lascia vedere come presa, invece di passare per fedeltà a quello che non ha più tempo.',
    'Più su di una presa riconosciuta questa forza non arriva: nel tuo caso il punto più alto è la mano che si sa chiusa, mentre l\'apertura della mano resta un\'altra materia.',
    'Al suo pieno rendimento il trattenere ti rende un servizio solo: dice con esattezza quanto costa; quel conto è tutto ciò che questa forza sa consegnare alla tua questione.',
