  'corona|La Temperanza|dritta': [
    'Di che cosa è fatto il massimo che questa forza porta alla tua questione: una proporzione sola, trovata a mano, fra due materie che non sembrano stare nello stesso recipiente. Nient\'altro, nessuna aggiunta.',
    'Il bene in gioco per la tua domanda è di specie lenta: non quantità di equilibrio, ma qualità della mescola, il tipo di calma che nasce quando due parti opposte stanno nella stessa misura senza sopraffarsi.',
    'Portata al suo meglio, questa forza dà alla tua questione una sola dose giusta: non la somma delle due spinte, nemmeno la vittoria di una, piuttosto un terzo stato che regge perché le contiene entrambe.',
  ],
  'corona|La Temperanza|capovolta': [
    'Questa forza, nella tua questione, sa indicare con precisione quale dose sta fuori misura e di quanto; quello che non arriva a darti è la mescola rifatta, perché separare le due parti non significa comporle.',
    'Il punto più alto di questa forza, per la tua domanda, è l\'eccesso guardato come eccesso e misurato: oltre quella misura non va, perché nominare uno squilibrio non è lo stesso che ridosarlo.',
    'Fra il ritmo rotto che la tua questione tiene adesso e la proporzione che potrebbe valerle c\'e\' lo spazio di due parti che tornano a parlarsi come due, ciascuna con il proprio nome, senza fondersi per fretta.',
  ],
  'corona|Il Diavolo|dritta': [
    'Di questo massimo fanno parte il nome esatto dell\'attaccamento che lavora nella tua questione, il tornaconto che lo tiene in piedi e la mano che ha stretto il patto senza accorgersene.',
    'Il bene possibile qui è di specie aspra, lucidità e non sollievo: la verità sul legame che la tua questione alimenta, guardato nella sua convenienza prima che nella sua vergogna.',
    'Quanto questa forza sa dare alla tua questione, al pieno, è una presa riconosciuta per quello che è: un patto con un vantaggio dentro, che smette di comandare nel buio quando viene chiamato per nome.',
  ],
  'corona|Il Diavolo|capovolta': [
    'Il più alto che questa forza dà alla tua questione è un nodo slacciato dalle stesse mani che lo avevano stretto: oltre lo scioglimento non va, perché non cancella la stagione in cui il patto conveniva.',
    'Fra la presa di adesso sulla tua questione e la presa che resterebbe dopo lo scioglimento c\'è tutta la distanza che questa forza può coprire, misurabile nel peso che si perde.',
    'Una catena vera si allenta quando chi l\'ha chiusa ne riconosce il meccanismo: questo è il massimo in gioco sulla tua questione; quello che non dà, nemmeno al meglio, è l\'innocenza di chi non l\'ha mai indossata.',
  ],
  'corona|La Torre|dritta': [
    'Il massimo qui è fatto di quello che resta quando una facciata viene giù: i muri che portavano carico, il nome vero delle cose dette male, il conto di quanto il tuo lavoro poggiava sul falso.',
    'Un cedimento improvviso può togliere alla tua questione ogni appoggio finto e lasciare materia solida su cui ricominciare; fuori dalla sua portata, anche al meglio, sta un passaggio indolore.',
    'Al suo meglio questa scossa lascia intatto il vero: quello che viene giù è la parte della tua costruzione che reggeva per convenzione; il solido non lo tocca il colpo.',
  ],
  'corona|La Torre|capovolta': [
    'Di che specie è il bene possibile qui: lucidità sul rimando e non quiete. Il più alto che questo rinvio sa dare alla tua questione è il nome dell\'impalcatura che tiene su una cosa sfiatata.',
    'Il tetto di questa forza è il tempo guadagnato: può rimandare lo smontaggio della tua costruzione e non può rendere vero quello che il rimando mantiene in piedi.',
