  'sotto|Asso di Bastoni|capovolta': [
    'Quello che le dita hanno appreso sul far scoccare un fuoco non si riconquista: sotto la tua faccenda sta quell\'abilità intatta, col ramo verde appoggiato al muro che nessuno ha acceso.',
