  'sotto|Cinque di Bastoni|capovolta': [
    'Quello che hai davanti è impastato di molte beghe minute, tutte lasciate aperte: bastoni alzati in aria che nessuno ha calato. Di quella materia la tua questione è fatta e su quella sta.',
